-- 3.15.1 Israel furniture-core price evidence v2.
-- Exact Israeli listings retrieved 2026-09-28. All offers remain candidates.
-- Displayed VAT treatment is unknown, so no ex-VAT normalized price is stored.

on conflict(source_id) do update set source_type=excluded.source_type,source_channel=excluded.source_channel,source_name=excluded.source_name,source_url=excluded.source_url,source_date=excluded.source_date,language_code=excluded.language_code,region=excluded.region,evidence=excluded.evidence,retrieved_at=now();

on conflict(material_code) do update set department=excluded.department,category_code=excluded.category_code,canonical_name=excluded.canonical_name,base_unit=excluded.base_unit,specifications=excluded.specifications,active=true,updated_at=now();

select material_id,'IL',case material_code
when 'confirmat_screw_7x50mm' then 'בורג דירקטה 50×7, 12 יחידות'
when 'minifix_bolt_direct_wood_16_15_short_neck' then 'בורג למזק 16/15 ישיר לעץ, הברגה גסה, צוואר קצר'
when 'minifix_cam_flat_15mm_board16' then 'מחבר מיניפיקס שטוח 15 אקסנטר ללוח 16 מ״מ'
when 'gas_spring_80n' then 'בוכנת גז 80N'
when 'gas_spring_100n' then 'בוכנת גז 100N'
when 'gas_spring_120n' then 'בוכנת גז 120N'
when 'corner_connector_plastic_dark_brown_pack10' then 'מחבר זוית פלסטיק חום כהה, 10 יחידות'
when 'corner_connector_plastic_light_brown_pack10' then 'מחבר זוית פלסטיק חום בהיר, 10 יחידות'
when 'corner_connector_plastic_white_pack10' then 'מחבר זוית פלסטיק לבן, 10 יחידות'
when 'magnet_rectangular_48x22x9mm' then 'מגנט מלבני 48×22×9 מ״מ, יחידה אחת בבליסטר'
when 'magnet_round_hole_32x5mm' then 'מגנט עגול עם חור 32×5 מ״מ, 2 יחידות בבליסטר'
when 'magnet_round_25x5mm' then 'מגנט עגול 25×5 מ״מ, 2 יחידות בבליסטר'
when 'reinforcement_strap_zinc_15x100mm' then 'סרגל חיזוק 15×100 אבץ'
when 'metal_angle_30x30x30mm' then 'זווית מתכת 30×30×30'
when 'chair_angle_zinc_15x50x50mm' then 'זווית כסא מתכת 15×50×50 אבץ'
when 'chair_angle_zinc_15x40x40mm' then 'זווית כסא מתכת 15×40×40 אבץ'
when 'chair_angle_zinc_15x25x25mm' then 'זווית כסא מתכת 15×25×25 אבץ'
end,'he-IL','{"market":"Israel","source_language":"Hebrew"}'::jsonb,'common'
from public.reference_materials where material_code in (
'confirmat_screw_7x50mm','minifix_bolt_direct_wood_16_15_short_neck','minifix_cam_flat_15mm_board16','gas_spring_80n','gas_spring_100n','gas_spring_120n',
'corner_connector_plastic_dark_brown_pack10','corner_connector_plastic_light_brown_pack10','corner_connector_plastic_white_pack10','magnet_rectangular_48x22x9mm','magnet_round_hole_32x5mm','magnet_round_25x5mm',
'reinforcement_strap_zinc_15x100mm','metal_angle_30x30x30mm','chair_angle_zinc_15x50x50mm','chair_angle_zinc_15x40x40mm','chair_angle_zinc_15x25x25mm')
on conflict(material_id,market_code,language_code) do update set market_name=excluded.market_name,local_specifications=excluded.local_specifications,availability_status=excluded.availability_status,active=true,updated_at=now();

on conflict(market_offer_id) do update set source_price=excluded.source_price,source_currency=excluded.source_currency,source_unit=excluded.source_unit,price_scope=excluded.price_scope,included_services=excluded.included_services,delivery_included=excluded.delivery_included,package_quantity=excluded.package_quantity,minimum_order_quantity=excluded.minimum_order_quantity,vat_mode=excluded.vat_mode,normalized_price_ex_vat=excluded.normalized_price_ex_vat,normalized_unit=excluded.normalized_unit,conversion_basis=excluded.conversion_basis,region=excluded.region,valid_from=excluded.valid_from,confidence=excluded.confidence,status=excluded.status;
